import{z as B,x as P,o as A,c as d,q as t,j as r,D as a,d as l,s as n,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"移动端 NPU 部署","description":"","frontmatter":{"title":"移动端 NPU 部署","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mobile-npu-deploy.md","filePath":"llm/mobile-npu-deploy.md","lastUpdated":1791063341000}'),s={name:"llm/mobile-npu-deploy.md"};function p(C,e,D,N,m,c){const o=P("Mermaid");return A(),d("div",null,[e[2]||(e[2]=t('<h1 id="移动端-npu-部署" tabindex="-1">移动端 NPU 部署 <a class="header-anchor" href="#移动端-npu-部署" aria-label="Permalink to &quot;移动端 NPU 部署&quot;">​</a></h1><div class="epigraph"><p>手机上的 TOPS 写在发布会上；LLM decode 要的是能持续吃带宽的矩阵核、以及不会把 8GB DRAM 吃光的 KV 预算。</p><footer>—— 对照 ExecuTorch / Core ML / NNAPI / 厂商 QNN 的端侧部署栈；量化与内存是硬约束</footer></div><p><a href="/llm/webgpu-inference">上一课</a>是浏览器沙箱。原生 App 可以走 NPU：Apple Neural Engine、高通 Hexagon、联发科 APU，经由 Core ML、NNAPI、QNN、ExecuTorch。本课写部署差：静态图编译、INT8/INT4、热包络、以及 decode 循环往往仍落在 CPU/GPU，因为 NPU 对动态 KV 不友好。不要把「设备有 45 TOPS」写成「70B 能跑」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NPU 喜欢固定形状卷积/GEMM。LLM 逐步 \\(n\\) 变、采样不规则、投机分支，编译器要么 pad 到 \\(n_{\\max}\\)（DRAM 炸），要么每步回 CPU。缺口是混合：投影与 FFN 下沉 NPU，注意力在 GPU/CPU；或整网 CPU 量化（llama.cpp 系）。切面选错的下场可算：每步把 KV 搬过一次运行时边界，带宽墙提前撞上，NPU 吃到的静态 GEMM 再快也白搭。</p><p>热功耗：持续 decode 会降频，峰值 TOPS 与持续 token/s 不是一回事——<a href="/llm/energy-per-token">每 token 能耗</a>在手机上直接决定能不能聊完一条消息。差距可以拆成三个机制。利用率：TOPS 是 MAC 阵列每周期全喂满的纸面数，decode 对每个权重只做一次乘加、算术强度在 \\(2\\) FLOP/字节量级，落在<a href="/llm/arithmetic-intensity-decode">屋顶线</a>的带宽区，阵列大部分时间在等数据。带宽墙：LPDDR 的带宽还要被 ISP、显示、modem 分食，权重每步都要重读，INT4 压的就是这条流量。内存驻留：权重、KV、系统与应用争同一颗 DRAM，KV 随上下文线性涨，8GB 机器上这条账先爆。所以「TOPS ÷ 模型 FLOPs」估 TPOT 的三个前提——满阵列、独享带宽、恒定时钟——在手机上一个都不成立。</p><p><span class="marginnote">TOPS 是「每秒多少万亿次运算」的纸面峰值，好比汽车的极速表——市区堵车（等数据）时永远开不到。decode 每读一个权重只做一次乘加，大部分时间在等内存送数，所以「45 TOPS 跑 70B」是发布会话术，不是工程事实。</span></p><p>后台：OS 会杀长时间 GPU/NPU 占用。产品要把生成切成可暂停步。</p><p><span class="marginnote">ExecuTorch 把 PyTorch 边下沉边解释；Core ML 转换对动态控制流不完整。选栈先看 generate 循环能不能留下，再看算子覆盖。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型级：1B–8B 级量化，上下文 2K–8K 量级起步——超出这个窗口，权重加 KV 的内存驻留在 8GB 机器上就排不下，那是容量问题，不是精度问题。KV 用量化或短窗。工具链：能导出的静态子图下 NPU，循环在运行时；判据是循环每步要不要跨运行时边界——每步跨界就多一次同步与搬运，比单个算子慢更伤。与分词：移动端分词必须 C++/Rust，不能起 Python，解释器的启动与常驻内存都按百 MB 计。UI 流式走稳定前缀。电量：测持续功率与降频曲线，不是芯片海报——峰值只撑几十秒，持续功率才是「聊完一条消息」的预算。</p><p><span class="marginnote">为什么 8GB 内存卡住上下文？粗算：4-bit 的 8B 模型权重约 4 GB，系统与 App 再占两三 GB，留给 KV 的只够几千 token——上下文一涨，先爆的不是精度，是内存。这就是「容量问题，不是精度问题」的含义。</span></p>',12)),(A(),r(i,null,{default:a(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%20--%3E%20Q%5B%22INT8%2FINT4%20%E8%BD%AC%E6%8D%A2%22%5D%0A%20%20Q%20--%3E%20SPLIT%5B%22%E9%9D%99%E6%80%81%E5%AD%90%E5%9B%BE%20%E2%86%92%20NPU%22%5D%0A%20%20Q%20--%3E%20LOOP%5B%22%E9%80%90%E6%AD%A5%E5%BE%AA%E7%8E%AF%E5%9C%A8%20CPU%2FGPU%22%5D%0A%20%20LOOP%20--%3E%20KV%5B%22%E7%9F%AD%E4%B8%8A%E4%B8%8B%E6%96%87%20%2F%20%E9%87%8F%E5%8C%96%20KV%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,"屋顶线：NPU 峰值高、能用的形状窄；decode 强度低，可能根本打不满 TOPS，瓶颈回到 DRAM。这与数据中心 decode 同构，只是绝对数字更差：HBM 换 LPDDR，功耗预算从几百瓦换到几瓦，可容忍的模型体积从百 GB 换到个位 GB。混合切面由此有了依据：FFN 与投影是大而静态的 GEMM，形状固定，下沉 NPU 吃矩阵核；注意力逐步读变长的 KV，形状动态，留在 CPU/GPU 反而快。厂商 SDK 的「LLM 方案」往往是自家核 + 私有格式，可移植性低于 ONNX。选择等于绑定 SoC。",-1)),e[5]||(e[5]=E("p",null,[E("span",{class:"marginnote"},"初学者容易以为「NPU 一定比 CPU 快，全放上去就对了」。实际每步 decode 都要在处理器之间搬数据时，搬运本身就能吃掉全部加速——像把菜在两个厨房之间来回端，灶再快也白费。切面选对比单核快慢更决定性。")],-1)),(A(),r(i,null,{default:a(()=>[n(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20OP%7B%22%E7%AE%97%E5%AD%90%E8%AF%A5%E6%94%BE%E5%93%AA%3F%22%7D%0A%20%20OP%20--%3E%7C%22%E6%8A%95%E5%BD%B1%20%2F%20FFN%3A%20%E5%BD%A2%E7%8A%B6%E5%9B%BA%E5%AE%9A%E7%9A%84%E5%A4%A7%20GEMM%22%7C%20NPU%5B%22%E4%B8%8B%E6%B2%89%20NPU%20%E5%90%83%E7%9F%A9%E9%98%B5%E6%A0%B8%22%5D%0A%20%20OP%20--%3E%7C%22%E6%B3%A8%E6%84%8F%E5%8A%9B%3A%20%E9%80%90%E6%AD%A5%E8%AF%BB%E5%8F%98%E9%95%BF%20KV%22%7C%20CPU%5B%22%E7%95%99%E5%9C%A8%20CPU%2FGPU%22%5D%0A%20%20OP%20--%3E%7C%22%E9%87%87%E6%A0%B7%20%2F%20%E6%8E%A9%E7%A0%81%3A%20%E5%9C%A8%E5%BE%AA%E7%8E%AF%E9%87%8C%22%7C%20RT%5B%22%E7%95%99%E5%9C%A8%E8%BF%90%E8%A1%8C%E6%97%B6%EF%BC%8C%E5%AD%90%E5%9B%BE%E5%8F%AA%E5%87%BA%20logits%22%5D%0A%20%20NPU%20--%3E%20CHK%7B%22%E5%BE%AA%E7%8E%AF%E6%AF%8F%E6%AD%A5%E8%A6%81%E8%B7%A8%E8%BF%90%E8%A1%8C%E6%97%B6%E8%BE%B9%E7%95%8C%E5%90%97%3F%22%7D%0A%20%20CPU%20--%3E%20CHK%0A%20%20CHK%20--%3E%7C%22%E8%A6%81%22%7C%20BAD%5B%22%E6%AF%8F%E6%AD%A5%E5%90%8C%E6%AD%A5%E6%90%AC%E8%BF%90%EF%BC%8C%E5%B8%A6%E5%AE%BD%E5%A2%99%E6%8F%90%E5%89%8D%E5%88%B0%22%5D%0A%20%20CHK%20--%3E%7C%22%E4%B8%8D%E8%A6%81%22%7C%20GOOD%5B%22%E5%AD%90%E5%9B%BE%E7%A8%B3%E5%AE%9A%E5%A4%8D%E7%94%A8%EF%BC%8C%E6%94%B6%E7%9B%8A%E8%90%BD%E5%9C%B0%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在 NPU 上假设任意 <a href="/llm/logit-bias">logit bias</a> 与文法掩码都能融合：采样在循环里，NPU 子图只出到 logits，采样逻辑能不能下沉先查 SDK。不要用峰值 TOPS 除以 FLOPs 估 TPOT。下一课：纯 CPU 量化路径（<a href="/llm/cpu-inference-quant">CPU 推理与量化</a>），反而更可移植。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>手机 NPU 适合静态子图；LLM decode 循环常留在 CPU/GPU。</li><li>峰值 TOPS ≠ 持续 token/s：利用率、带宽墙、内存驻留、热四条账。</li><li>模型要小、KV 要短、权重要量化。</li><li>分词与 generate 必须在原生运行时。</li><li>SoC SDK 绑定与可移植性权衡。</li><li>出处：ExecuTorch；Core ML；NNAPI；厂商 QNN 文档。</li></ul>',4))])}const F=B(s,[["render",p]]);export{T as __pageData,F as default};
